#include <bits/stdc++.h>
using namespace std;
string readAll() {
    string s;
    char buf[1 << 16];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, stdin)) > 0) s.append(buf, n);
    return s;
}
int main() {
    string data = readAll();
    size_t p1 = data.find('\n');
    string header = data.substr(0, p1);
    string s;
    if (p1 != string::npos) {
        size_t p2 = data.find('\n', p1 + 1);
        s = data.substr(p1 + 1, p2 == string::npos ? string::npos : p2 - p1 - 1);
    }
    int lo, hi, u;
    { istringstream in(header); in >> lo >> hi >> u; }
    // Decode UTF-8: code point values and byte offsets, so a window is lo code points.
    vector<uint32_t> cp;
    vector<size_t> off;
    for (size_t i = 0; i < s.size();) {
        unsigned char c = s[i];
        int len = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
        uint32_t v = len == 1 ? c : len == 2 ? (c & 0x1F) : len == 3 ? (c & 0x0F) : (c & 0x07);
        for (int j = 1; j < len; j++) v = (v << 6) | (s[i + j] & 0x3F);
        cp.push_back(v); off.push_back(i);
        i += len;
    }
    off.push_back(s.size());
    long long count = cp.size();
    string_view sv(s);
    unordered_map<string_view, int> counts;
    int best = 0;
    uint32_t window[32];
    for (long long i = 0; i + lo <= count; i++) {
        copy(cp.begin() + i, cp.begin() + i + lo, window);
        sort(window, window + lo);
        int distinct = unique(window, window + lo) - window;
        if (distinct <= u) best = max(best, ++counts[sv.substr(off[i], off[i + lo] - off[i])]);
    }
    cout << best << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        String[] lines = new String(System.in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8).split("\n", -1);
        StringTokenizer header = new StringTokenizer(lines[0]);
        int lo = Integer.parseInt(header.nextToken());
        Integer.parseInt(header.nextToken());
        int u = Integer.parseInt(header.nextToken());
        // Work on code points so a window is lo characters even outside the BMP.
        int[] cp = lines.length > 1 ? lines[1].codePoints().toArray() : new int[0];
        HashMap<String, Integer> counts = new HashMap<>();
        int best = 0;
        int[] window = new int[lo];
        for (int i = 0; i + lo <= cp.length; i++) {
            System.arraycopy(cp, i, window, 0, lo);
            Arrays.sort(window);
            int distinct = 1;
            for (int j = 1; j < lo; j++) if (window[j] != window[j - 1]) distinct++;
            if (distinct <= u) best = Math.max(best, counts.merge(new String(cp, i, lo), 1, Integer::sum));
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"bytes"
	"sort"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	lines := bytes.SplitN(data, []byte("\n"), 3)
	header := bytes.Fields(lines[0])
	lo, _ := strconv.Atoi(string(header[0]))
	u, _ := strconv.Atoi(string(header[2]))
	var s []rune // code points, so a window is lo characters
	if len(lines) > 1 {
		s = []rune(string(lines[1]))
	}
	counts := map[string]int{}
	best := 0
	window := make([]rune, lo)
	for i := 0; i+lo <= len(s); i++ {
		copy(window, s[i:i+lo])
		sort.Slice(window, func(a, b int) bool { return window[a] < window[b] })
		distinct := 1
		for j := 1; j < lo; j++ {
			if window[j] != window[j-1] {
				distinct++
			}
		}
		if distinct <= u {
			key := string(s[i : i+lo])
			counts[key]++
			best = max(best, counts[key])
		}
	}
	w.WriteString(strconv.Itoa(best) + "\n")
}
